def run(L_main, ff=1.0, C=150e-6, T=8.0, dt=2e-5, a_bg=0.15, f_bg=45.0, Vd=0.15, Rs=5000., clV=3.3, Rcl=100., Rlk=1e7, Il=200e-9):
    b=nom.beam({**main_base,'length_mm':L_main}); z=main_base['damping_ratio']
    k=b['k']/(ff**3); m=b['m']; c=2*z*np.sqrt(k*m); th=b['theta']; cp=b['cp']; fm=b['forcing_mass']
    w=2*np.pi*f_bg
    def sp(z_,xi=1e-3): return xi*np.log1p(np.exp(min(z_/xi,50)))
    def f(y,t):
        x,v,vp,vs=y
        ab=a_bg*g*np.sin(w*t)
        acc=(-c*v-k*x-th*vp-fm*ab)/m
        ig=th*v
        ir=np.sign(vp)*sp(abs(vp)-vs-2*Vd)/Rs
        icl=np.sign(vp)*sp(abs(vp)-clV)/Rcl
        vpd=(ig-ir-icl)/cp
        dvs=(ir-vs/Rlk-Il)/C
        return np.array([v,acc,vpd,dvs])
    y=np.zeros(4); n=int(T/dt); t=0.; vs_rec=[]; ts=[]
    for i in range(n):
        k1=f(y,t);k2=f(y+0.5*dt*k1,t+0.5*dt);k3=f(y+0.5*dt*k2,t+0.5*dt);k4=f(y+dt*k3,t+dt)
        y=y+dt/6*(k1+2*k2+2*k3+k4);t+=dt
        if i%500==0: vs_rec.append(y[3]); ts.append(t)
    return np.array(ts),np.array(vs_rec)
t0=time.time()
for ff in [0.9,1.0,1.1]:
    for L in [24,29.5,35,42]:
        ts,vs=run(L,ff=ff,T=8.0)
        print(f"ff={ff} L={L}: vs(final)={vs[-1]:.2f} vsmax={vs.max():.2f}")
print('elapsed',time.time()-t0)
